// Throwaway check: what does Gemma support on Google's OpenAI-compatible endpoint?
// Run with: node --env-file=.env hosted-check.mjs   (never prints the key)
const base = "https://generativelanguage.googleapis.com/v1beta/openai";
const key = process.env.HOSTED_API_KEY || process.env.GEMINI_API_KEY;
const model = process.argv[2] || "gemma-4-31b-it";
if (!key) throw new Error("no key in env");

async function call(label, body) {
  const t0 = Date.now();
  const res = await fetch(`${base}/chat/completions`, {
    method: "POST",
    headers: { "content-type": "application/json", authorization: `Bearer ${key}` },
    body: JSON.stringify({ model, ...body }),
  });
  const ms = Date.now() - t0;
  const text = await res.text();
  let out = text;
  try {
    const j = JSON.parse(text);
    const m = j.choices?.[0]?.message;
    out = m
      ? JSON.stringify({ content: m.content?.slice(0, 300), tool_calls: m.tool_calls, finish: j.choices[0].finish_reason, usage: j.usage })
      : JSON.stringify(j).slice(0, 600);
  } catch {}
  console.log(`\n[${label}] HTTP ${res.status} in ${ms} ms\n${out.replaceAll(key, "<key>")}`);
}

const sys = { role: "system", content: "You are a terse technical interviewer." };

await call("plain + system", { messages: [sys, { role: "user", content: "Ask one question about JWT refresh tokens." }] });

await call("json_object", {
  messages: [{ role: "user", content: 'Return JSON {"score": number 0-4, "reason": string} for the answer "I used JWT because it is stateless".' }],
  response_format: { type: "json_object" },
});

await call("json_schema", {
  messages: [{ role: "user", content: 'Score the answer "I used JWT because it is stateless" from 0 to 4.' }],
  response_format: {
    type: "json_schema",
    json_schema: {
      name: "evaluation",
      schema: { type: "object", properties: { score: { type: "integer" }, reason: { type: "string" } }, required: ["score", "reason"] },
    },
  },
});

await call("tool call", {
  messages: [{ role: "user", content: "Open src/auth.ts and tell me what it does. Use the tool." }],
  tools: [
    {
      type: "function",
      function: {
        name: "readFile",
        description: "Read a file from the candidate's repo",
        parameters: { type: "object", properties: { path: { type: "string" } }, required: ["path"] },
      },
    },
  ],
});

