// Throwaway check 2: system role, thinking control, latency. Never prints the key.
const base = "https://generativelanguage.googleapis.com/v1beta/openai";
const key = process.env.HOSTED_API_KEY || process.env.GEMINI_API_KEY;
const model = process.argv[2] || "gemma-4-31b-it";

async function call(label, body) {
  const t0 = Date.now();
  const res = await fetch(`${base}/chat/completions`, {
    method: "POST",
    headers: { "content-type": "application/json", authorization: `Bearer ${key}` },
    body: JSON.stringify({ model, ...body }),
  });
  const ms = Date.now() - t0;
  const text = await res.text();
  let out = text.slice(0, 400);
  try {
    const j = JSON.parse(text);
    const m = j.choices?.[0]?.message;
    if (m) out = JSON.stringify({ content: m.content?.slice(0, 220), finish: j.choices[0].finish_reason, usage: j.usage });
  } catch {}
  console.log(`\n[${model} | ${label}] HTTP ${res.status} in ${ms} ms\n${out.replaceAll(key, "<key>")}`);
}

const q = { role: "user", content: "Ask one short interview question about JWT refresh tokens." };
const sys = { role: "system", content: "You are a terse technical interviewer." };

await call("user only", { messages: [q] });
await call("system + user", { messages: [sys, q] });
await call("system + user (retry)", { messages: [sys, q] });
await call("reasoning_effort none", { messages: [q], reasoning_effort: "none" });
await call("reasoning_effort low", { messages: [q], reasoning_effort: "low" });
await call("thinking_budget 0", {
  messages: [q],
  extra_body: { google: { thinking_config: { thinking_budget: 0 } } },
});
await call("json_schema, effort none", {
  messages: [{ role: "user", content: 'Score the answer "I used JWT because it is stateless" from 0 to 4.' }],
  reasoning_effort: "none",
  response_format: {
    type: "json_schema",
    json_schema: {
      name: "evaluation",
      schema: { type: "object", properties: { score: { type: "integer" }, reason: { type: "string" } }, required: ["score", "reason"] },
    },
  },
});

