// Throwaway: how long does the raw brief-sized call take, with and without streaming? Never prints the key.
import { readFileSync } from "node:fs";
const key = process.env.HOSTED_API_KEY;
const model = "gemma-4-26b-a4b-it";
const size = Number(process.argv[2] ?? 24000);

// Build a prompt of roughly `size` characters from real fixture files.
const dir = "fixtures/portfolio-new/files/";
const files = ["README.md", "package.json", "src/App.tsx", "src/data/projects.ts", "src/pages/ProjectDetailPage.tsx", "src/components/About.tsx", "src/components/Header.tsx", "src/components/Hero.tsx"];
let context = "";
for (const f of files) {
  if (context.length >= size) break;
  context += `--- ${f} ---\n${readFileSync(dir + f, "utf8").slice(0, 4000)}\n\n`;
}
context = context.slice(0, size);
const prompt = `${context}\n\nWrite a JSON object with keys: summary (2 sentences), stack (array of strings), hooks (array of 6 objects with kind, ref, file, why). Reply with only JSON.`;

const t0 = Date.now();
const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`, {
  method: "POST",
  headers: { "content-type": "application/json", "x-goog-api-key": key },
  signal: AbortSignal.timeout(170000),
  body: JSON.stringify({
    contents: [{ role: "user", parts: [{ text: prompt }] }],
    generationConfig: { thinkingConfig: { thinkingLevel: "minimal" } },
  }),
}).catch((e) => ({ ok: false, status: "fetch-error", text: async () => String(e) }));
const ms = Date.now() - t0;
const text = await res.text();
let out = text.slice(0, 300);
try {
  const j = JSON.parse(text);
  const parts = j.candidates?.[0]?.content?.parts;
  if (parts) out = JSON.stringify({ outChars: parts.map((p) => p.text ?? "").join("").length, usage: j.usageMetadata, finish: j.candidates[0].finishReason });
  else if (j.error) out = j.error.message.slice(0, 300);
} catch {}
console.log(`promptChars=${prompt.length} HTTP ${res.status} in ${ms} ms\n${out.replaceAll(key, "<key>")}`);

