/**
 * Server-side: turn what the user typed (or the repo id stored in the interview state)
 * back into a readable repo.
 *
 * The API routes are stateless, so every turn needs the repo again in order to open files.
 * A small in-memory cache avoids asking GitHub for the file list on every turn.
 * It holds no user data: only the file list of public repos, for 30 minutes.
 */
import { existsSync } from "node:fs";
import { FIXTURE_NAMES, loadFixture, type FixtureName } from "../ingest/fixture";
import { loadGitHubRepo, parseGitHubUrl } from "../ingest/github";
import { loadLocalRepo } from "../ingest/local";
import type { RepoSource } from "../ingest/types";

export function isLocalMode(): boolean {
  return process.env.LOCAL_MODE === "true";
}

/** The sample repos shown as buttons on the start screen. Their briefs are cached in fixtures/briefs/. */
export const SAMPLES: { id: FixtureName; label: string; description: string }[] = [
  { id: "viva", label: "Viva (this project)", description: "TypeScript, Next.js, Mastra. Has Entire checkpoints, so Viva asks about AI-written code." },
  { id: "vidyut-mitra", label: "Vidyut Mitra", description: "Python backend + Next.js dashboard: a WhatsApp agent that explains electricity bills." },
  { id: "portfolio-new", label: "Portfolio", description: "Vite + React personal portfolio site." },
];

const CACHE_MS = 30 * 60 * 1000;
const cache = new Map<string, { source: RepoSource; at: number }>();

function remember(source: RepoSource): RepoSource {
  cache.set(source.id, { source, at: Date.now() });
  // Keep the cache small: drop anything older than the limit.
  for (const [id, entry] of cache) if (Date.now() - entry.at > CACHE_MS) cache.delete(id);
  return source;
}

/** A friendly error the UI can show as-is. */
export class UserError extends Error {}

/**
 * Resolves the start-screen input: "sample:<name>", a GitHub URL or owner/repo,
 * or (local mode only) a folder path on this machine.
 */
export async function resolveTarget(target: string): Promise<RepoSource> {
  const input = target.trim();
  if (!input) throw new UserError("Paste a GitHub repository URL to begin.");

  if (input.startsWith("sample:")) {
    const name = input.slice("sample:".length);
    if (!(FIXTURE_NAMES as readonly string[]).includes(name)) throw new UserError("Unknown sample repo.");
    return remember(loadFixture(name as FixtureName));
  }

  // A folder path is only accepted in local mode, and only if it exists on this machine.
  if (isLocalMode() && !input.startsWith("http") && existsSync(/*turbopackIgnore: true*/ input)) {
    return remember(await loadLocalRepo(input));
  }

  if (!parseGitHubUrl(input)) {
    throw new UserError(isLocalMode() ? "Enter a GitHub repository URL or a folder path that exists on this computer." : "Enter a public GitHub repository URL, for example https://github.com/owner/repo.");
  }
  try {
    return remember(await loadGitHubRepo(input));
  } catch (err) {
    throw new UserError(err instanceof Error ? err.message : "Could not read that repository.");
  }
}

/** Gets the repo back from the id stored in the interview state ("fixture:x", "github:o/r", "local:<path>"). */
export async function resolveRepoId(repoId: string): Promise<RepoSource> {
  const cached = cache.get(repoId);
  if (cached && Date.now() - cached.at < CACHE_MS) return cached.source;

  if (repoId.startsWith("fixture:")) return resolveTarget(`sample:${repoId.slice("fixture:".length)}`);
  if (repoId.startsWith("github:")) return resolveTarget(repoId.slice("github:".length));
  if (repoId.startsWith("local:")) {
    if (!isLocalMode()) throw new UserError("Local folders can only be read in local mode.");
    return resolveTarget(repoId.slice("local:".length));
  }
  throw new UserError("Unknown repository.");
}

/** Small helpers shared by the API routes, so each route stays a few lines long. */
import type { z } from "zod";
import { UserError } from "./sources";

/** Reads and validates a JSON request body. Throws a UserError with a readable message if it is wrong. */
export async function readBody<T>(request: Request, schema: z.ZodType<T>): Promise<T> {
  let json: unknown;
  try {
    json = await request.json();
  } catch {
    throw new UserError("The request body is not valid JSON.");
  }
  const parsed = schema.safeParse(json);
  if (!parsed.success) {
    const issue = parsed.error.issues[0];
    throw new UserError(`Invalid request: ${issue.path.join(".") || "body"} ${issue.message}`);
  }
  return parsed.data;
}

/**
 * Runs a route handler and turns any error into a JSON response.
 * A UserError is the user's to fix (400, message shown as-is); anything else is ours (500, generic message).
 */
export async function handle(run: () => Promise<unknown>): Promise<Response> {
  try {
    return Response.json(await run());
  } catch (err) {
    if (err instanceof UserError) return Response.json({ error: err.message }, { status: 400 });
    // The details go to the server log only: never echo internal errors (or prompts) to the browser.
    console.error("[viva] route error:", err instanceof Error ? err.message : err);
    return Response.json({ error: "Something went wrong on our side. Please try again." }, { status: 500 });
  }
}

/** POST /api/ingest: repo -> project brief, AI-written areas, and last session's weak spots. */
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { z } from "zod";
import { createBrief } from "@/lib/interview/brief";
import { ProjectBriefSchema } from "@/lib/interview/schemas";
import { addAiHooks, aiWrittenAreas, loadProvenance } from "@/lib/provenance";
import { handle, readBody } from "@/lib/server/http";
import { resolveTarget } from "@/lib/server/sources";
import { memoryStatus, recallWeakSpots } from "@/mastra/memory";

const Body = z.object({
  target: z.string().max(500),
  /** The candidate's one-line correction to a brief they have already seen. */
  correction: z.string().max(500).optional(),
});

export async function POST(request: Request) {
  return handle(async () => {
    const { target, correction } = await readBody(request, Body);
    const source = await resolveTarget(target);
    const { provenance, checkpointCount, hint } = await loadProvenance(source);

    // Sample repos have a brief saved by the eval run, so a visitor gets it instantly and it costs
    // no model tokens. A correction always goes to the model, because the brief has to change.
    const saved = path.resolve(/*turbopackIgnore: true*/ process.cwd(), "fixtures/briefs", `${source.label}.json`);
    const useSaved = source.id.startsWith("fixture:") && !correction && existsSync(saved);

    let brief;
    let inventedPathsDropped = 0;
    let filesUsed: string[] = [];
    let usedFallback = false;
    if (useSaved) {
      brief = ProjectBriefSchema.parse(JSON.parse(readFileSync(saved, "utf8")));
    } else {
      const result = await createBrief(source, { correction });
      brief = addAiHooks(result.brief, provenance);
      inventedPathsDropped = result.inventedPathsDropped;
      filesUsed = result.filesUsed.map((file) => file.path);
      usedFallback = result.meta.usedFallback;
    }

    return {
      repoId: source.id,
      repoLabel: source.label,
      filePaths: source.files.map((file) => file.path),
      brief,
      provenance,
      aiAreas: aiWrittenAreas(provenance),
      checkpointCount,
      provenanceHint: hint,
      filesUsed,
      inventedPathsDropped,
      usedFallback,
      cached: useSaved,
      previousWeakSpots: await recallWeakSpots(source.id),
      memory: memoryStatus(),
    };
  });
}

/** POST /api/turn: one interview turn. The whole interview state comes in and goes back out. */
import { z } from "zod";
import { InterviewStateSchema } from "@/lib/interview/schemas";
import { endEarly, runTurn } from "@/lib/interview/turn";
import { handle, readBody } from "@/lib/server/http";
import { resolveRepoId } from "@/lib/server/sources";
import { createAgentDeps } from "@/mastra/deps";

const Body = z.object({
  state: InterviewStateSchema,
  /** The candidate's answer to the pending question. Left out on the very first turn. */
  answer: z.string().max(6000).optional(),
  /** "end" stops the interview: no more questions, the report covers what was answered. */
  action: z.enum(["end"]).optional(),
});

export async function POST(request: Request) {
  return handle(async () => {
    const { state, answer, action } = await readBody(request, Body);
    if (action === "end") return { state: endEarly(state), done: true, toolActivity: [] };

    // The repo is looked up again from its id so the agent's tools can open files.
    const source = await resolveRepoId(state.repoId);
    const turn = await runTurn(state, answer, createAgentDeps(source, state.settings, state.provenance));
    return {
      state: turn.state,
      evaluation: turn.evaluation,
      nextQuestion: turn.nextQuestion,
      done: turn.done,
      toolActivity: turn.toolActivity,
    };
  });
}

/** POST /api/report: the final report. In local mode it also saves the weak spots for next time. */
import { z } from "zod";
import { buildReport, reportToMarkdown, weakSpotsToRemember } from "@/lib/interview/report";
import { InterviewStateSchema } from "@/lib/interview/schemas";
import { handle, readBody } from "@/lib/server/http";
import { saveWeakSpots } from "@/mastra/memory";

const Body = z.object({ state: InterviewStateSchema });

export async function POST(request: Request) {
  return handle(async () => {
    const { state } = await readBody(request, Body);
    const { report, meta } = await buildReport(state);
    const today = new Date().toISOString().slice(0, 10);
    // saveWeakSpots does nothing and returns false in hosted mode.
    const saved = await saveWeakSpots(state.repoId, weakSpotsToRemember(report, today));
    return { report, markdown: reportToMarkdown(report, state.repoLabel), savedToMemory: saved, usedFallback: meta.usedFallback };
  });
}

/** DELETE /api/memory: "forget this project". Only does anything in local mode. */
import { z } from "zod";
import { handle, readBody } from "@/lib/server/http";
import { forgetProject } from "@/mastra/memory";

const Body = z.object({ repoId: z.string().max(500) });

export async function DELETE(request: Request) {
  return handle(async () => {
    const { repoId } = await readBody(request, Body);
    return { forgotten: await forgetProject(repoId) };
  });
}

/**
 * GET /api/health: a tiny endpoint for uptime checks.
 * Pinging it every 5 minutes keeps the free Render instance from going to sleep (DECISIONS D7).
 */
import { getModelName, getProvider } from "@/lib/llm/provider";
import { isLocalMode } from "@/lib/server/sources";

export async function GET() {
  return Response.json({ ok: true, mode: isLocalMode() ? "local" : "hosted", provider: getProvider(), model: getModelName() });
