/** Browser-side helpers for calling Viva's API routes. Types mirror what the routes return. */
import type { AiWrittenArea } from "../provenance/parse";
import type { Evaluation, InterviewState, ProjectBrief, ProvenanceEntry, Question, Report, WeakSpot } from "../interview/schemas";

export type IngestResult = {
  repoId: string;
  repoLabel: string;
  filePaths: string[];
  brief: ProjectBrief;
  provenance: ProvenanceEntry[];
  aiAreas: AiWrittenArea[];
  checkpointCount: number;
  provenanceHint: string | null;
  filesUsed: string[];
  inventedPathsDropped: number;
  usedFallback: boolean;
  cached: boolean;
  previousWeakSpots: WeakSpot[];
  memory: { enabled: boolean; label: string };
};

export type TurnResult = {
  state: InterviewState;
  evaluation?: Evaluation;
  nextQuestion?: Question;
  done: boolean;
  toolActivity: string[];
};

export type ReportResult = { report: Report; markdown: string; savedToMemory: boolean; usedFallback: boolean };

/** Sends JSON and returns JSON. On any failure it throws an Error whose message is safe to show the user. */
async function send<T>(path: string, body: unknown, method: "POST" | "DELETE" = "POST"): Promise<T> {
  let res: Response;
  try {
    res = await fetch(path, { method, headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
  } catch {
    throw new Error("Could not reach Viva. Is the server still running?");
  }
  const data = (await res.json().catch(() => null)) as (T & { error?: string }) | null;
  if (!res.ok || !data) {
    if (res.status === 429) throw new Error(data?.error ?? "Too many requests. Please wait a minute and try again.");
    throw new Error(data?.error ?? "Something went wrong. Please try again.");
  }
  return data;
}

export const api = {
  ingest: (target: string, correction?: string) => send<IngestResult>("/api/ingest", { target, correction }),
  turn: (state: InterviewState, answer?: string) => send<TurnResult>("/api/turn", { state, answer }),
  end: (state: InterviewState) => send<TurnResult>("/api/turn", { state, action: "end" }),
  report: (state: InterviewState) => send<ReportResult>("/api/report", { state }),
  forget: (repoId: string) => send<{ forgotten: boolean }>("/api/memory", { repoId }, "DELETE"),
};

/** Small shared building blocks so every screen looks the same. */
import type { ButtonHTMLAttributes, ReactNode } from "react";

export function Button({ variant = "primary", className = "", ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: "primary" | "ghost" }) {
  const styles =
    variant === "primary"
      ? "bg-emerald-600 text-white hover:bg-emerald-500 disabled:bg-zinc-700 disabled:text-zinc-400"
      : "border border-zinc-700 text-zinc-200 hover:bg-zinc-800 disabled:text-zinc-600";
  return <button {...props} className={`rounded-md px-4 py-2 text-sm font-medium transition-colors disabled:cursor-not-allowed ${styles} ${className}`} />;
}

export function Badge({ children, tone = "neutral" }: { children: ReactNode; tone?: "neutral" | "green" | "amber" | "violet" }) {
  const tones = {
    neutral: "border-zinc-700 text-zinc-300",
    green: "border-emerald-700 text-emerald-300",
    amber: "border-amber-700 text-amber-300",
    violet: "border-violet-700 text-violet-300",
  };
  return <span className={`inline-block rounded-full border px-2.5 py-0.5 text-xs ${tones[tone]}`}>{children}</span>;
}

export function Card({ title, children }: { title?: string; children: ReactNode }) {
  return (
    <section className="rounded-lg border border-zinc-800 bg-zinc-900/60 p-5">
      {title ? <h2 className="mb-3 text-sm font-semibold uppercase tracking-wide text-zinc-400">{title}</h2> : null}
      {children}
    </section>
  );
}

export function ErrorNote({ message, onRetry }: { message: string; onRetry?: () => void }) {
  return (
    <div role="alert" className="flex items-center justify-between gap-4 rounded-md border border-red-900 bg-red-950/50 px-4 py-3 text-sm text-red-200">
      <span>{message}</span>
      {onRetry ? (
        <button onClick={onRetry} className="shrink-0 underline underline-offset-2 hover:text-white">
          Try again
        </button>
      ) : null}
    </div>
  );
}

