"use client";

/** Screen 3: the interview itself, as a chat. */
import { useEffect, useRef, useState } from "react";
import type { InterviewState, Question } from "@/lib/interview/schemas";
import { mainQuestionCount } from "@/lib/interview/state";
import { Badge, Button, ErrorNote } from "./ui";

const ROUND_LABELS: Record<Question["round"], string> = {
  retest: "Retest from last session",
  overview: "Overview",
  decisions: "Decisions",
  "deep-dive": "Deep dive",
  "failure-scale": "Failure and scale",
  "wrap-up": "Wrap-up",
};

export function InterviewScreen(props: {
  state: InterviewState;
  /** What the agent did before each question (questionId -> lines such as "reading src/auth.ts"). */
  activity: Record<string, string[]>;
  busy: boolean;
  error: string | null;
  onAnswer: (answer: string) => void;
  onEnd: () => void;
  onRetry: () => void;
}) {
  const { state } = props;
  const [draft, setDraft] = useState("");
  const bottom = useRef<HTMLDivElement>(null);

  const current = state.questions[state.questions.length - 1];
  const waitingForAnswer = current !== undefined && !state.answers.some((answer) => answer.questionId === current.id);
  const asked = mainQuestionCount(state);

  // Keep the newest message in view.
  useEffect(() => {
    bottom.current?.scrollIntoView({ behavior: "smooth" });
  }, [state.questions.length, state.answers.length, props.busy]);

  const submit = (text: string) => {
    if (props.busy) return;
    setDraft("");
    props.onAnswer(text);
  };

  return (
    <div className="space-y-4">
      <header className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex flex-wrap items-center gap-2">
          <h1 className="text-xl font-semibold">{state.repoLabel}</h1>
          {current ? <Badge tone="green">{ROUND_LABELS[current.round]}</Badge> : null}
          <Badge>
            Question {asked} of {state.roundPlan.length}
          </Badge>
          <Badge>{state.settings.persona === "tough" ? "Tough tech lead" : "Friendly HR round"}</Badge>
        </div>
        <Button variant="ghost" disabled={props.busy} onClick={props.onEnd}>
          End early
        </Button>
      </header>

      <div className="h-1.5 overflow-hidden rounded-full bg-zinc-800">
        <div className="h-full bg-emerald-600 transition-all" style={{ width: `${(asked / state.roundPlan.length) * 100}%` }} />
      </div>

      <div className="space-y-4">
        {state.questions.map((question) => {
          const answer = state.answers.find((a) => a.questionId === question.id);
          const evaluation = state.evaluations.find((e) => e.questionId === question.id);
          const lines = props.activity[question.id] ?? [];
          return (
            <div key={question.id} className="space-y-3">
              <div className="max-w-3xl rounded-lg border border-zinc-800 bg-zinc-900 p-4">
                <div className="mb-1.5 flex flex-wrap items-center gap-2 text-xs text-zinc-400">
                  <span>Interviewer</span>
                  {question.isFollowUp ? <Badge>follow-up</Badge> : null}
                  {question.aboutAiCode ? <Badge tone="violet">AI-written code</Badge> : null}
                  {question.retestTopic ? <Badge tone="amber">retest</Badge> : null}
                </div>
                <p className="text-zinc-100">{question.text}</p>
                {lines.length > 0 ? <p className="mt-2 text-xs text-zinc-500">Before asking, Viva was {lines.join(", then ")}.</p> : null}
              </div>
              {answer ? (
                <div className="ml-auto max-w-3xl rounded-lg border border-emerald-900 bg-emerald-950/40 p-4">
                  <div className="mb-1.5 flex items-center gap-2 text-xs text-zinc-400">
                    <span>You</span>
                    {evaluation ? <Badge tone={evaluation.score >= 3 ? "green" : "amber"}>{answer.skipped ? "skipped" : `${evaluation.score}/4`}</Badge> : null}
                  </div>
                  <p className="whitespace-pre-wrap text-zinc-100">{answer.skipped ? "(skipped)" : answer.text}</p>
                </div>
              ) : null}
            </div>
          );
        })}
        {props.busy ? <p className="text-sm text-zinc-400">Viva is reading your answer and preparing the next question...</p> : null}
        <div ref={bottom} />
      </div>

      {props.error ? <ErrorNote message={props.error} onRetry={props.onRetry} /> : null}

      {waitingForAnswer ? (
        <form
          className="space-y-3"
          onSubmit={(event) => {
            event.preventDefault();
            if (draft.trim()) submit(draft.trim());
          }}
        >
          <textarea
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            onKeyDown={(event) => {
              // Ctrl+Enter (or Cmd+Enter) sends the answer.
              if (event.key === "Enter" && (event.ctrlKey || event.metaKey) && draft.trim()) submit(draft.trim());
            }}
            rows={5}
            maxLength={6000}
            disabled={props.busy}
            placeholder="Type your answer. Ctrl+Enter to send."
            className="w-full rounded-md border border-zinc-700 bg-zinc-950 px-3 py-2 text-sm outline-none focus:border-emerald-600"
          />
          <div className="flex flex-wrap gap-3">
            <Button type="submit" disabled={props.busy || draft.trim() === ""}>
              Send answer
            </Button>
            <Button type="button" variant="ghost" disabled={props.busy} onClick={() => submit("")}>
              Skip / I don&apos;t know
            </Button>
            <Button type="button" variant="ghost" disabled title="Voice answers arrive with the ElevenLabs phase">
              Mic (later phase)
            </Button>
          </div>
        </form>
      ) : null}
    </div>
  );
}

"use client";

/** Screen 4: the scored report, with Markdown export. */
import { useState } from "react";
import type { ReportResult } from "@/lib/client/api";
import { Badge, Button, Card } from "./ui";

function downloadText(filename: string, text: string) {
  const url = URL.createObjectURL(new Blob([text], { type: "text/markdown" }));
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  link.click();
  URL.revokeObjectURL(url);
}

function List({ items, empty }: { items: string[]; empty: string }) {
  if (items.length === 0) return <p className="text-sm text-zinc-500">{empty}</p>;
  return (
    <ul className="list-disc space-y-1.5 pl-5 text-sm text-zinc-200">
      {items.map((item, index) => (
        <li key={index}>{item}</li>
      ))}
    </ul>
  );
}

export function ReportScreen(props: { repoLabel: string; result: ReportResult; memoryLabel: string; onRestart: () => void }) {
  const { report, markdown, savedToMemory } = props.result;
  const [copied, setCopied] = useState(false);

  return (
    <div className="space-y-5">
      <header className="flex flex-wrap items-center justify-between gap-3">
        <h1 className="text-2xl font-semibold">Report: {props.repoLabel}</h1>
        <div className="flex gap-3">
          <Button variant="ghost" onClick={() => downloadText("viva-report.md", markdown)}>
            Download Markdown
          </Button>
          <Button
            variant="ghost"
            onClick={async () => {
              await navigator.clipboard.writeText(markdown);
              setCopied(true);
            }}
          >
            {copied ? "Copied" : "Copy Markdown"}
          </Button>
          <Button onClick={props.onRestart}>New interview</Button>
        </div>
      </header>

      <Card>
        <div className="flex flex-wrap items-baseline gap-4">
          <span className="text-4xl font-semibold">{report.overall}</span>
          <span className="text-zinc-400">out of 4</span>
          <Badge tone={report.overall >= 2.5 ? "green" : "amber"}>{report.readiness}</Badge>
        </div>
        <p className="mt-3 text-sm text-zinc-400">{savedToMemory ? "Your weak spots were saved on this computer and will be retested next time." : props.memoryLabel}</p>
      </Card>

      {report.progressVsLast.length > 0 ? (
        <Card title="Progress since last session">
          <ul className="space-y-1.5 text-sm">
            {report.progressVsLast.map((item) => (
              <li key={item.topic} className="flex flex-wrap items-center gap-2">
                <span className="text-zinc-100">{item.topic}</span>
                <Badge tone={item.after > item.before ? "green" : "amber"}>
                  {item.before}/4 then, {item.after}/4 now
                </Badge>
              </li>
            ))}
          </ul>
        </Card>
      ) : null}

      <div className="grid gap-5 md:grid-cols-2">
        <Card title="Strengths">
          <List items={report.strengths} empty="Nothing stood out yet." />
        </Card>
        <Card title="Weak spots">
          <List items={report.weakSpots.map((spot) => `${spot.topic}: ${spot.evidence}`)} empty="No weak spots found." />
        </Card>
        <Card title="Revise before the real interview">
          <List items={report.revisionList} empty="Nothing to revise." />
        </Card>
        <Card title="Likely next questions">
          <List items={report.likelyNextQuestions} empty="None suggested." />
        </Card>
      </div>

      <Card title="How you said it">
        <p className="text-sm text-zinc-400">{report.deliverySummary ?? "Delivery feedback (pace, filler words, pauses) is available for voice answers, which arrive in a later phase."}</p>
      </Card>

      <Card title="Question by question">
        <div className="space-y-4">
          {report.perQuestion.map((item) => (
            <div key={item.questionId} className="border-l-2 border-zinc-700 pl-4">
              <div className="mb-1.5 flex flex-wrap items-center gap-2 text-xs">
                <Badge>{item.round}</Badge>
                {item.isFollowUp ? <Badge>follow-up</Badge> : null}
                {item.aboutAiCode ? <Badge tone="violet">AI-written code</Badge> : null}
                <Badge tone={item.score >= 3 ? "green" : "amber"}>{item.skipped ? "skipped" : `${item.score}/4`}</Badge>
              </div>
              <p className="text-sm text-zinc-100">{item.question}</p>
              <p className="mt-1.5 text-sm text-zinc-400">{item.answerSummary}</p>
              {item.good.length > 0 ? <p className="mt-1.5 text-sm text-emerald-300">Good: {item.good.join("; ")}</p> : null}
              {item.missing.length > 0 ? <p className="mt-1 text-sm text-amber-300">Missing: {item.missing.join("; ")}</p> : null}
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
}

