// Throwaway: walk the API the way the UI does, against a running server.
const base = process.argv[2] ?? "http://localhost:3100";
const post = async (path, body, method = "POST") => {
  const t0 = Date.now();
  const res = await fetch(base + path, { method, headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
  return { status: res.status, ms: Date.now() - t0, data: await res.json() };
};

const health = await (await fetch(base + "/api/health")).json();
console.log("health:", JSON.stringify(health));

const bad = await post("/api/ingest", { target: "not a repo" });
console.log(`bad url -> ${bad.status}: ${bad.data.error}`);
const invalid = await post("/api/turn", { state: { nope: true } });
console.log(`invalid state -> ${invalid.status}: ${invalid.data.error}`);
const missing = await post("/api/ingest", { target: "https://github.com/AbdulWasih05/this-repo-does-not-exist-xyz" });
console.log(`missing repo -> ${missing.status}: ${missing.data.error}`);

const ingest = await post("/api/ingest", { target: "sample:viva" });
const i = ingest.data;
console.log(`ingest sample:viva -> ${ingest.status} in ${ingest.ms} ms, cached=${i.cached}, hooks=${i.brief.hooks.length}, aiAreas=${i.aiAreas.length}, checkpoints=${i.checkpointCount}, memory=${i.memory.enabled}`);

// Build the initial state the same way the browser does (createInterviewState), via a tiny inline copy of its output shape.
const plan = ["overview", "decisions", "deep-dive", "failure-scale", "wrap-up"];
let state = {
  repoId: i.repoId, repoLabel: i.repoLabel, filePaths: i.filePaths, brief: i.brief, provenance: i.provenance,
  previousWeakSpots: i.previousWeakSpots, settings: { persona: "tough", mainQuestions: 5, maxFollowUps: 2, targetRole: "SDE" },
  roundPlan: plan, questions: [], answers: [], evaluations: [], delivery: [], endedEarly: false,
};

let turn = await post("/api/turn", { state });
console.log(`turn 0 -> ${turn.status} in ${turn.ms} ms: [${turn.data.nextQuestion.round}] ${turn.data.nextQuestion.text.slice(0, 110)}`);
state = turn.data.state;

const answers = [
  "Viva reads a repo, builds a brief with Gemma, and runs a mock interview. It is a Next.js app; a Mastra agent writes code questions and plain functions run the state machine and scoring.",
  "skip",
  "Decisions are in code and wording is by the model, because a small model is unreliable at flow control and I wanted deterministic scoring.",
];
for (const answer of answers) {
  turn = await post("/api/turn", { state, answer });
  state = turn.data.state;
  const q = turn.data.nextQuestion;
  console.log(`turn -> ${turn.status} in ${turn.ms} ms: score ${turn.data.evaluation?.score}${turn.data.evaluation?.skipped ? " (skipped)" : ""}; activity=${JSON.stringify(turn.data.toolActivity)}; next [${q?.round}${q?.isFollowUp ? " follow-up" : ""}${q?.aboutAiCode ? " AI" : ""}] ${q?.text.slice(0, 150)}`);
}

const ended = await post("/api/turn", { state, action: "end" });
console.log(`end -> ${ended.status}, done=${ended.data.done}, questions kept=${ended.data.state.questions.length}`);
const report = await post("/api/report", { state: ended.data.state });
console.log(`report -> ${report.status} in ${report.ms} ms: overall ${report.data.report.overall}, ${report.data.report.readiness}, saved=${report.data.savedToMemory}, markdown ${report.data.markdown.length} chars`);

