// One-off patch: wire the per-IP rate limit into the routes and the error handler.
const fs = require("fs");
const root = "C:/Users/Home/Desktop/open-source/Personal-viva/";
function patch(file, pairs) {
  let t = fs.readFileSync(root + file, "utf8").replace(/\r\n/g, "\n");
  for (const [a, b] of pairs) {
    if (!t.includes(a)) throw new Error(file + " missing: " + a.slice(0, 70));
    t = t.replace(a, () => b);
  }
  fs.writeFileSync(root + file, t);
}

patch("src/lib/server/http.ts", [
  [`import { UserError } from "./sources";`, `import { RateLimitError } from "./rate-limit";\nimport { UserError } from "./sources";`],
  [
    `    if (err instanceof UserError) return Response.json({ error: err.message }, { status: 400 });`,
    `    if (err instanceof UserError) return Response.json({ error: err.message }, { status: 400 });
    if (err instanceof RateLimitError) {
      return Response.json({ error: err.message }, { status: 429, headers: { "retry-after": String(err.retryAfterSec) } });
    }`,
  ],
]);

for (const [file, kind, anchor] of [
  ["src/app/api/ingest/route.ts", "ingest", `    const { target, correction } = await readBody(request, Body);`],
