]) {
  patch(file, [
    [anchor, `    enforceRateLimit(request, "${kind}");\n${anchor}`],
    [`import { handle, readBody } from "@/lib/server/http";`, `import { handle, readBody } from "@/lib/server/http";\nimport { enforceRateLimit } from "@/lib/server/rate-limit";`],
