/**
 * Sentry setup for the server. Loaded once by src/instrumentation.ts.
 *
 * Tracing only starts when SENTRY_DSN is set, so the app runs the same without it.
 * Privacy rule (PRD F8): traces carry metadata only. No prompt, answer or code text is sent.
 */
import * as Sentry from "@sentry/nextjs";

Sentry.init({
  dsn: process.env.SENTRY_DSN,
  enabled: Boolean(process.env.SENTRY_DSN),
  // Every interview turn is traced. Traffic is tiny, so there is no need to sample.
  tracesSampleRate: 1.0,
  // Never attach IP addresses, cookies or request bodies (the body holds the candidate's answers).
  sendDefaultPii: false,
  integrations: [
    // Automatic spans for AI SDK calls, with the prompt and the reply text switched off.
    Sentry.vercelAIIntegration({ recordInputs: false, recordOutputs: false }),
  ],
  beforeSendTransaction(event) {
    // SENTRY_DEBUG_SPANS=true prints a one-line summary of each trace to the server log,
    // so the span names and attributes can be checked without opening Sentry.
    if (process.env.SENTRY_DEBUG_SPANS === "true") {
      const spans = (event.spans ?? []).map((span) => {
        const viva = Object.entries(span.data ?? {}).filter(([key]) => key.startsWith("viva.") || key.startsWith("gen_ai."));
        return `${span.op ?? "?"}{${viva.map(([key, value]) => `${key}=${value}`).join(",")}}`;
      });
      console.info(`[viva] trace "${event.transaction}": ${spans.join(" ")}`);
    }
    return event;
  },
});

