const fs = require("fs");
const root = "C:/Users/Home/Desktop/open-source/Personal-viva/";
const read = (p) => fs.readFileSync(root + p, "utf8").replace(/\r\n/g, "\n");
function patch(file, pairs) {
  let t = read(file);
  for (const [a, b] of pairs) {
    if (!t.includes(a)) throw new Error(file + " missing: " + a.slice(0, 80));
    t = t.replace(a, () => b);
  }
  fs.writeFileSync(root + file, t);
}

