// One-off: collect the [POST] and [WHY] lines from PROGRESS.md into docs/post/notes.md,
// and strip email addresses from the saved `entire checkpoint explain` excerpts.
const fs = require("fs");
const root = "C:/Users/Home/Desktop/open-source/Personal-viva/";
const progress = fs.readFileSync(root + "docs/PROGRESS.md", "utf8").replace(/\r\n/g, "\n");

const sections = [];
let current = null;
for (const line of progress.split("\n")) {
  if (line.startsWith("## ")) {
    current = { title: line.slice(3), post: [], why: [] };
    sections.push(current);
  } else if (current && /^\s*- /.test(line) && line.includes("`[POST]`")) {
    const clean = line.trim();
    (line.includes("`[WHY]`") ? current.why : current.post).push(clean);
  } else if (current && /^\s*- /.test(line) && line.includes("`[WHY]`")) {
    current.why.push(line.trim());
  }
}

const out = [
  "# Post notes",
  "",
  "Every line tagged `[POST]` or `[WHY]` in `docs/PROGRESS.md`, grouped by phase. Collected by script; the wording is unchanged.",
  "Each number here was measured on the date and in the way its line says. Check a number against `docs/PROGRESS.md` before quoting it.",
  "",
];
let post = 0;
let why = 0;
for (const section of sections) {
  if (section.post.length + section.why.length === 0) continue;
  out.push(`## ${section.title}`, "");
  if (section.post.length) out.push("**Numbers and facts**", "", ...section.post, "");
  if (section.why.length) out.push("**Why this code exists (bugs and their fixes)**", "", ...section.why, "");
  post += section.post.length;
  why += section.why.length;
}
fs.writeFileSync(root + "docs/post/notes.md", out.join("\n"));

const dir = root + "docs/post/entire/";
for (const file of fs.readdirSync(dir)) {
  const text = fs.readFileSync(dir + file, "utf8").replace(/\r\n/g, "\n").replace(/ <[^>\s]+@[^>\s]+>/g, "");
  fs.writeFileSync(dir + file, text);
}
console.log(`notes: ${post} [POST] lines, ${why} [WHY] lines; excerpts cleaned: ${fs.readdirSync(dir).length}`);

