// Throwaway: ingest a real GitHub repo on the live site and take two turns.
const base = process.argv[2];
const target = process.argv[3];
const post = async (path, body) => {
  const t0 = Date.now();
  const res = await fetch(base + path, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
  return { status: res.status, ms: Date.now() - t0, data: await res.json().catch(() => ({})) };
};
const ingest = await post("/api/ingest", { target });
const i = ingest.data;
if (ingest.status !== 200) {
  console.log(`ingest -> ${ingest.status}: ${i.error}`);
  process.exit(0);
}
console.log(`ingest ${target} -> 200 in ${ingest.ms} ms: files=${i.filePaths.length}, filesUsed=${i.filesUsed.length}, hooks=${i.brief.hooks.length}, invented dropped=${i.inventedPathsDropped}, fallback=${i.usedFallback}, checkpoints=${i.checkpointCount}`);
console.log(`summary: ${i.brief.summary.slice(0, 220)}`);
console.log(`stack: ${i.brief.stack.join(", ")}`);
console.log(`hook files real: ${i.brief.hooks.filter((h) => h.file).every((h) => i.filePaths.includes(h.file))}`);
console.log(`provenance hint: ${i.provenanceHint?.slice(0, 80)}`);

let state = {
  repoId: i.repoId, repoLabel: i.repoLabel, filePaths: i.filePaths, brief: i.brief, provenance: i.provenance,
  previousWeakSpots: [], settings: { persona: "friendly", mainQuestions: 5, maxFollowUps: 1, targetRole: "Backend engineer" },
  roundPlan: ["overview", "decisions", "deep-dive", "failure-scale", "wrap-up"], questions: [], answers: [], evaluations: [], delivery: [], endedEarly: false,
};
let turn = await post("/api/turn", { state });
console.log(`turn 0 -> ${turn.status} in ${turn.ms} ms: ${turn.data.nextQuestion?.text.slice(0, 160)}`);
state = turn.data.state;
turn = await post("/api/turn", { state, answer: "skip" });
state = turn.data.state;
turn = await post("/api/turn", { state, answer: "We chose Flask with a Twilio webhook because WhatsApp is where our users already are; the alternative was a mobile app, which rural users would not install." });
console.log(`turn 2 -> ${turn.status} in ${turn.ms} ms: score ${turn.data.evaluation?.score}; activity=${JSON.stringify(turn.data.toolActivity)}; next [${turn.data.nextQuestion?.round}] ${turn.data.nextQuestion?.text.slice(0, 200)}`);

