// One-off: log the merge, the deploy check, the Sentry run and the IP-address fix.
const fs = require("fs");
const root = "C:/Users/Home/Desktop/open-source/Personal-viva/";
const read = (p) => fs.readFileSync(root + p, "utf8").replace(/\r\n/g, "\n");

const mark = "### Research notes for later phases";
const decisions = read("docs/DECISIONS.md");
if (!decisions.includes(mark)) throw new Error("marker missing");
fs.writeFileSync(
  root + "docs/DECISIONS.md",
  decisions.replace(
    mark,
    () =>
      `## After the merge (5 Oct 2026)

- **D87. Sentry must not record visitor IP addresses.** \`[WHY]\` The first real trace in Sentry showed \`user.ip_address\` on the turn span (\`::1\`, because it came from a local run). On the hosted site that would have been each visitor's address, against the "metadata only" rule. Fix: \`dataCollection\` in \`Sentry.init\` turns off user info, cookies, headers, query strings, request bodies and model inputs and outputs, and \`beforeSendSpan\` deletes visitor-identifying attributes as a second line of defence. This supersedes the "not checked yet" note in D84.
- **D88. Six squash commits on \`main\`** for the whole build (Wasih's choice, to keep the contribution graph small): phases 0 to 4 one each, then phases 5, 7 and the post material as one. Each stacked branch was rebased onto the new \`main\` before its squash-merge, because a squash commit is not an ancestor of the next branch and the merge would otherwise conflict.
- **D89. The demo runs without \`GITHUB_TOKEN\`** (Wasih's choice). GitHub's 60 requests per hour is enough for a demo: sample repos use none.

` + mark,
  ),
);

fs.writeFileSync(
  root + "docs/PROGRESS.md",
  read("docs/PROGRESS.md").replace(/\s*$/, "\n") +
    `
## 5 Oct 2026: merge, deploy check, real Sentry traces, IP-address fix

- **Merged:** PRs #1 to #5 and #8 squash-merged into \`main\` (6 commits); #6 and #7 closed because #8 contained them. The combined tree passed typecheck, lint, 69 tests and a production build before the last merge.
- \`[POST]\` **Live on Render:** https://viva-ou6t.onrender.com . The blueprint built on the first try. Checked through the API on 5 Oct: health; three error cases returned HTTP 400 with clear messages; the Viva sample brief in 0.5 s; turns of 5 to 18 s including a follow-up, a skip and a question after the agent read \`src/mastra/index.ts\`; end early; report in 12.9 s.
- \`[POST]\` **A real repo on the live site:** \`AbdulWasih05/vidyut-mitra\` pasted as a GitHub URL: brief in 44 s from 13 of 94 files, 8 hooks, 0 invented paths, every hook file real. It has no Entire checkpoints, so the hint was shown instead of AI-written areas.
- **Not checked on the live site:** the pages were not clicked through in a browser; only the API was exercised.
- \`[POST]\` **Real Sentry traces.** Three short interviews (one per sample, 4 turns each) run locally against the real DSN produced 12 turn spans, 21 model-call spans and 10 tool spans. Wasih confirmed them in Sentry. Screenshot \`docs/post/sentry-turn-span.png\`: a deep-dive turn with \`viva.ai_authored_question=true\`, \`viva.question_names_real_file=true\`, \`viva.tool_calls=1\`, no repair, no fallback, 12.66 s.
- \`[POST]\` **The grounding check caught one.** Another real trace shows \`viva.followup_references_answer=false\`: Gemma's follow-up claimed to build on the answer, but the phrase it quoted was not in it.
- \`[POST]\` \`[WHY]\` **Sentry was recording IP addresses.** The screenshot above shows \`user.ip_address\` on the span. Fixed in DECISIONS D87; after the fix a local run with \`SENTRY_DEBUG_SPANS=true\` listed no visitor attribute on any AI span. Not yet re-checked in the Sentry UI, and the live site needs a redeploy to pick it up.
`,
);

let phases = read("docs/PHASES.md");
const swap = (a, b) => {
  if (!phases.includes(a)) throw new Error("missing: " + a.slice(0, 60));
  phases = phases.replace(a, () => b);
};
swap(
  "- [ ] **7.4a** 3 traced interviews and screenshots into `docs/post/` (needs `SENTRY_DSN`)",
  "- [x] **7.4a** 3 traced interviews and screenshots into `docs/post/` (needs `SENTRY_DSN`): done 5 Oct, `docs/post/sentry-turn-span.png`",
);
swap(
  "  - [ ] Check in the Sentry UI that the automatic HTTP spans carry no request bodies (needs a DSN)",
  "  - [x] Sentry UI showed `user.ip_address` on spans; switched off (DECISIONS D87)\n  - [ ] Re-check in the Sentry UI after redeploying that no IP address or request body is attached",
);
swap("- [ ] **5.2 Deploy**", "- [x] **5.2 Deploy**");
swap(
  "- [ ] **5.5 Verify** the live URL from a fresh browser: full interview end to end",
  "- [ ] **5.5 Verify** the live URL from a fresh browser: full interview end to end\n  - [x] Walked through the API on the live URL (sample and a real GitHub repo)\n  - [ ] Clicked through in a browser",
);
fs.writeFileSync(root + "docs/PHASES.md", phases);
console.log("ok");

